// Photo-derived decorative relief; depth is artistically estimated from one view.
const packedPoints="";
const packedEdges="";
const bytes=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
const p=bytes(packedPoints),e=bytes(packedEdges);
export const portraitPoints=Array.from({length:p.length/6},(_,i)=>({x:p[i*6]+p[i*6+1]*256,y:p[i*6+2]+p[i*6+3]*256,z:p[i*6+4],light:p[i*6+5]/255}));
export const portraitEdges=Array.from({length:e.length/4},(_,i)=>[e[i*4]+e[i*4+1]*256,e[i*4+2]+e[i*4+3]*256]);
